#!/usr/bin/env python3
"""One-off recovery drill. Identity is read from SSH stdin and used only in process memory."""
import os,sys,json,subprocess,hashlib,secrets,time
from pathlib import Path
B=Path('/opt/blariyo/backup');PG='postgres:18@sha256:4ef4dbc939d61acea57712655ddb4b4ab27419c913f94cca0cd57cb3ea3c2280'
def run(args,data=None,timeout=180):
 r=subprocess.run(args,input=data,capture_output=True,timeout=timeout)
 assert r.returncode==0,'RESTORE_COMMAND_FAILED'
 return r.stdout
assert os.geteuid()==0 and Path('/etc/hostname').read_text().strip()=='ip-172-26-1-91'
identity=sys.stdin.buffer.read();assert b'AGE-SECRET-KEY-1' in identity
m=json.loads((B/'latest.json').read_text());spool=Path(m['spool']);assert spool.parent==B/'spool'
api=json.loads(run(['docker','inspect','blariyo-app-api-1']))[0]['Image']
script="const fs=require('fs'),{S3Client,GetObjectCommand}=require('@aws-sdk/client-s3');const c=JSON.parse(fs.readFileSync('/run/r2.json'));const s=new S3Client({region:'auto',endpoint:c.endpoint,credentials:{accessKeyId:c.accessKeyId,secretAccessKey:c.secretAccessKey}});s.send(new GetObjectCommand({Bucket:c.bucket,Key:process.argv[1]})).then(async r=>{for await(const b of r.Body){if(!process.stdout.write(b))await new Promise(v=>process.stdout.once('drain',v));}}).catch(()=>process.exitCode=1).finally(()=>s.destroy());"
encrypted=run(['docker','run','--rm','--network','blariyo-app_app','--read-only','--user','0','--cap-drop','ALL','--security-opt','no-new-privileges:true','--memory','192m','--pids-limit','32','--log-driver','none','--mount',f'type=bind,src={B}/r2.json,dst=/run/r2.json,readonly','--entrypoint','node',api,'-e',script,m['key']])
assert hashlib.sha256(encrypted).hexdigest()==m['sha256'] and len(encrypted)==m['bytes']
readback=spool/'restore-readback.age';readback.write_bytes(encrypted);os.chmod(readback,0o600)
# -i - reads the identity from stdin; plaintext stays in memory and then pg_restore stdin.
print('PASS R2 다운로드 SHA-256',flush=True)
archive=run(['age','--decrypt','-i','-',str(readback)],identity);assert archive.startswith(b'PGDMP')
print('PASS age 복호화',flush=True)
name='blariyo-restore-check-'+secrets.token_hex(6);created=False
try:
 run(['docker','run','-d','--name',name,'--network','none','--memory','256m','--pids-limit','64','--log-driver','none','--tmpfs','/var/lib/postgresql:size=256m','-e','POSTGRES_HOST_AUTH_METHOD=trust','-e','POSTGRES_DB=blariyo_restore',PG,'postgres','-c','shared_buffers=32MB','-c','max_connections=10']);created=True
 for _ in range(60):
  if subprocess.run(['docker','exec',name,'pg_isready','-h','127.0.0.1','-U','postgres','-d','blariyo_restore'],capture_output=True).returncode==0:break
  time.sleep(.5)
 else:raise RuntimeError('RESTORE_DB_NOT_READY')
 run(['docker','exec','-i',name,'pg_restore','-U','postgres','-d','blariyo_restore','--exit-on-error','--single-transaction','--no-owner','--no-acl'],archive)
 print('PASS 격리 pg_restore 완료',flush=True)
 query="SELECT (SELECT count(*) FROM ops.schema_migration), (SELECT count(*) FROM legal.policy_version WHERE status='EFFECTIVE'), (SELECT count(*) FROM content.board), (SELECT count(*) FROM content.board_post); SELECT policy_type,version_label,encode(sha256(convert_to(body_html,'UTF8')),'hex') FROM legal.policy_version WHERE status='EFFECTIVE' ORDER BY policy_type; SELECT version,encode(checksum_sha256,'hex') FROM ops.schema_migration ORDER BY version;"
 def sql(container,db):return run(['docker','exec','-i','--user','postgres',container,'psql','-XAtq','-v','ON_ERROR_STOP=1','-U','postgres','-d',db],query.encode())
 restored=sql(name,'blariyo_restore');current=sql('blariyo-db-postgresql-1','blariyo');assert restored==current,'RESTORE_READBACK_MISMATCH'
 print('PASS R2 실파일 다운로드·SHA-256·age 복호화·격리 PostgreSQL 18 실제 복원')
 print('PASS migration ledger·정책 본문 해시·게시판/게시글 수 운영 DB 대조')
 snapshot_sql="SELECT json_build_object('posts',(SELECT md5(string_agg(row_to_json(p)::text,'' ORDER BY id)) FROM content.board_post p),'items',(SELECT md5(string_agg(row_to_json(i)::text,'' ORDER BY id)) FROM collect.batch_item i),'reviews',(SELECT md5(string_agg(row_to_json(r)::text,'' ORDER BY item_id)) FROM collect.batch_review r));"
 def local_sql(q):return run(['docker','exec','-i','--user','postgres',name,'psql','-XAtq','-v','ON_ERROR_STOP=1','-U','postgres','-d','blariyo_restore'],q.encode())
 before=local_sql(snapshot_sql)
 local_sql("BEGIN;\n-- Approve/reject the snapshot read by the operator without a REVIEWING transition.\n-- Existing REVIEWING rows are read as UNREVIEWED; do not rewrite expired originals.\nCREATE OR REPLACE FUNCTION collect.guard_batch_review() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n IF NEW.status NOT IN ('APPROVED','REJECTED') THEN\n   RAISE EXCEPTION 'invalid review decision' USING ERRCODE='23514';\n END IF;\n IF TG_OP='INSERT' THEN\n   IF NEW.lock_version<>1 OR NEW.post_id IS NOT NULL THEN\n     RAISE EXCEPTION 'invalid initial review' USING ERRCODE='23514';\n   END IF;\n ELSE\n   IF OLD.post_id IS NOT NULL OR NEW.item_id<>OLD.item_id OR NEW.source_key<>OLD.source_key\n     OR NEW.source_post_key IS DISTINCT FROM OLD.source_post_key OR NEW.canonical_url_hash<>OLD.canonical_url_hash\n     OR NEW.lock_version<>OLD.lock_version+1 THEN\n     RAISE EXCEPTION 'invalid review update' USING ERRCODE='23514';\n   END IF;\n   IF NEW.post_id IS NOT NULL AND (OLD.status<>'APPROVED' OR NEW.status<>'APPROVED'\n     OR NEW.item_version<>OLD.item_version OR NEW.content_digest<>OLD.content_digest) THEN\n     RAISE EXCEPTION 'stale reviewed item' USING ERRCODE='23514';\n   END IF;\n END IF;\n RETURN NEW;\nEND $$;\n\n-- API-owned display codes; never an approval or parser configuration.\nCREATE TABLE content.source_code (\n source_key VARCHAR(80) PRIMARY KEY CHECK(source_key ~ '^[a-z][a-z0-9-]{0,79}$'),\n display_name VARCHAR(200) NOT NULL CHECK(length(btrim(display_name)) BETWEEN 1 AND 200 AND display_name=btrim(display_name)),\n lock_version INTEGER NOT NULL DEFAULT 1 CHECK(lock_version>=1),\n created_by VARCHAR(100) NOT NULL CHECK(created_by ~ '^(admin:v[1-9][0-9]*:[A-Za-z0-9_-]{43}|system:migration)$'),\n created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(),\n updated_by VARCHAR(100) NOT NULL CHECK(updated_by ~ '^(admin:v[1-9][0-9]*:[A-Za-z0-9_-]{43}|system:migration)$'),\n updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(),\n CHECK(updated_at>=created_at)\n);\nCREATE FUNCTION content.guard_source_code() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n IF NEW.source_key<>OLD.source_key OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at\n   OR NEW.lock_version<>OLD.lock_version+1 THEN\n   RAISE EXCEPTION 'invalid source code update' USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER guard_source_code BEFORE UPDATE ON content.source_code FOR EACH ROW EXECUTE FUNCTION content.guard_source_code();\nINSERT INTO content.source_code(source_key,display_name,created_by,updated_by) VALUES\n ('arcalive','아카라이브','system:migration','system:migration'),\n ('bobaedream','보배드림','system:migration','system:migration'),\n ('clien','클리앙','system:migration','system:migration'),\n ('dcinside','디시인사이드','system:migration','system:migration'),\n ('dmitory','디미토리','system:migration','system:migration'),\n ('dogdrip','개드립','system:migration','system:migration'),\n ('etoland','이토랜드','system:migration','system:migration'),\n ('fmkorea','에펨코리아','system:migration','system:migration'),\n ('goodgag','고급유머','system:migration','system:migration'),\n ('humoruniv','웃긴대학','system:migration','system:migration'),\n ('instiz','인스티즈','system:migration','system:migration'),\n ('inven','인벤','system:migration','system:migration'),\n ('mlbpark','MLBPARK','system:migration','system:migration'),\n ('natepann','네이트판','system:migration','system:migration'),\n ('pgr21','PGR21','system:migration','system:migration'),\n ('ppomppu','뽐뿌','system:migration','system:migration'),\n ('ruliweb','루리웹','system:migration','system:migration'),\n ('theqoo','더쿠','system:migration','system:migration'),\n ('todayhumor','오늘의유머','system:migration','system:migration'),\n ('youtube-community','유튜브 커뮤니티','system:migration','system:migration'),\n ('yuldo','율도','system:migration','system:migration');\nREVOKE ALL ON content.source_code FROM PUBLIC;\n\n-- Migrate display metadata only. Collector identities and existing post snapshots stay unchanged.\nLOCK TABLE content.source_code IN ACCESS EXCLUSIVE MODE;\nDO $$ BEGIN\n IF EXISTS(WITH source_code_mapping(source_key,code) AS (VALUES\n ('theqoo','thqo'),('ppomppu','pmpu'),('yuldo','yldo'),('inven','invn'),('dogdrip','dgdp'),('ruliweb','rlwb'),\n ('arcalive','arca'),('bobaedream','bbae'),('clien','clin'),('dcinside','dcid'),('dmitory','dmtr'),('etoland','etld'),\n ('fmkorea','fmkr'),('goodgag','ggag'),('humoruniv','hmun'),('instiz','inst'),('mlbpark','mlbp'),('natepann','ntpn'),\n ('pgr21','pgr2'),('todayhumor','tdhm'),('youtube-community','ytcm')\n ) SELECT 1 FROM content.source_code s LEFT JOIN source_code_mapping m USING(source_key) WHERE m.code IS NULL) THEN\n   RAISE EXCEPTION 'COMMON_CODES_UNMAPPED_SOURCE_KEY';\n END IF;\nEND $$;\nCREATE TABLE content.common_code_group (\n group_key VARCHAR(40) PRIMARY KEY CHECK(group_key ~ '^[a-z][a-z0-9_-]{0,39}$'),\n display_name VARCHAR(200) NOT NULL CHECK(length(btrim(display_name)) BETWEEN 1 AND 200 AND display_name=btrim(display_name)),\n lock_version INTEGER NOT NULL DEFAULT 1 CHECK(lock_version>=1),\n created_by VARCHAR(100) NOT NULL CHECK(created_by ~ '^(admin:v[1-9][0-9]*:[A-Za-z0-9_-]{43}|system:migration)$'),\n created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(),\n updated_by VARCHAR(100) NOT NULL CHECK(updated_by ~ '^(admin:v[1-9][0-9]*:[A-Za-z0-9_-]{43}|system:migration)$'),\n updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(),\n CHECK(updated_at>=created_at)\n);\nCREATE TABLE content.common_code (\n group_key VARCHAR(40) NOT NULL REFERENCES content.common_code_group(group_key),\n code VARCHAR(40) NOT NULL CHECK(code ~ '^[a-z0-9][a-z0-9_-]{0,39}$'),\n display_name VARCHAR(200) NOT NULL CHECK(length(btrim(display_name)) BETWEEN 1 AND 200 AND display_name=btrim(display_name)),\n reference_key VARCHAR(80),\n lock_version INTEGER NOT NULL DEFAULT 1 CHECK(lock_version>=1),\n created_by VARCHAR(100) NOT NULL CHECK(created_by ~ '^(admin:v[1-9][0-9]*:[A-Za-z0-9_-]{43}|system:migration)$'),\n created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(),\n updated_by VARCHAR(100) NOT NULL CHECK(updated_by ~ '^(admin:v[1-9][0-9]*:[A-Za-z0-9_-]{43}|system:migration)$'),\n updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(),\n PRIMARY KEY(group_key,code), UNIQUE(group_key,reference_key),\n CHECK(updated_at>=created_at),\n CHECK((group_key='source' AND code ~ '^[a-z][a-z0-9]{3}$' AND reference_key IS NOT NULL AND reference_key ~ '^[a-z][a-z0-9-]{0,79}$')\n   OR (group_key<>'source' AND reference_key IS NULL))\n);\nCREATE FUNCTION content.guard_common_code() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n IF NEW.group_key<>OLD.group_key OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at\n   OR NEW.lock_version<>OLD.lock_version+1 THEN\n   RAISE EXCEPTION 'invalid common code update' USING ERRCODE='23514';\n END IF;\n IF TG_TABLE_NAME='common_code' THEN\n   IF NEW.code<>OLD.code OR NEW.reference_key IS DISTINCT FROM OLD.reference_key THEN\n     RAISE EXCEPTION 'immutable common code identity' USING ERRCODE='23514';\n   END IF;\n END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER guard_common_code_group BEFORE UPDATE ON content.common_code_group FOR EACH ROW EXECUTE FUNCTION content.guard_common_code();\nCREATE TRIGGER guard_common_code BEFORE UPDATE ON content.common_code FOR EACH ROW EXECUTE FUNCTION content.guard_common_code();\nINSERT INTO content.common_code_group(group_key,display_name,created_by,updated_by) VALUES('source','출처','system:migration','system:migration');\nWITH source_code_mapping(source_key,code) AS (VALUES\n ('theqoo','thqo'),('ppomppu','pmpu'),('yuldo','yldo'),('inven','invn'),('dogdrip','dgdp'),('ruliweb','rlwb'),\n ('arcalive','arca'),('bobaedream','bbae'),('clien','clin'),('dcinside','dcid'),('dmitory','dmtr'),('etoland','etld'),\n ('fmkorea','fmkr'),('goodgag','ggag'),('humoruniv','hmun'),('instiz','inst'),('mlbpark','mlbp'),('natepann','ntpn'),\n ('pgr21','pgr2'),('todayhumor','tdhm'),('youtube-community','ytcm')\n)\nINSERT INTO content.common_code(group_key,code,display_name,reference_key,lock_version,created_by,created_at,updated_by,updated_at)\n SELECT 'source',m.code,s.display_name,s.source_key,s.lock_version,s.created_by,s.created_at,s.updated_by,s.updated_at\n FROM content.source_code s JOIN source_code_mapping m USING(source_key);\nDROP TABLE content.source_code;\nDROP FUNCTION content.guard_source_code();\nREVOKE ALL ON content.common_code_group,content.common_code FROM PUBLIC;\n\nCOMMIT;")
 assert local_sql(snapshot_sql)==before,'MIGRATION_DATA_CHANGED'
 assert local_sql("SELECT count(*) FROM content.common_code WHERE group_key='source'").strip()==b'21','COMMON_CODES_INCOMPLETE'
 print('PASS 격리 복원 DB API V011-V013 실행, 공통코드21, 게시글·수집·검수 데이터 해시 보존')

finally:
 if created:run(['docker','rm','-f',name])
 readback.unlink(missing_ok=True)
print('PASS 복구 시험 container·메모리 임시 DB 정리, 복구키 서버 파일 저장 없음')
